import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { exitWithError, requireDatabaseUrl } from './errors.ts';
import { createDb } from './index.ts';
import { backupDatabase, isEntryPoint, migrationsFolder, pendingMigrations } from './maintenance.ts';

/**
 * Applies SQL migrations in apps/server/drizzle (generated by `npm run db:generate`).
 * With `backup: true` a JSON backup of every table is written to backups/ first, but only when there is
 * something to apply (so normal restarts do not produce backups).
 */
export async function runMigrations(url: string, opts: { backup?: boolean; log?: (msg: string) => void } = {}) {
  if (opts.backup) {
    // Errors are not swallowed here: if the check fails we must not go on and migrate without a backup.
    const pending = await pendingMigrations(url);
    // A brand-new database (nothing applied yet) has nothing to back up.
    const fresh = pending.length > 0 && pending[0].startsWith('0000_');
    if (pending.length && !fresh) {
      const file = await backupDatabase(url, `before-migrate-${pending.join('+')}`);
      opts.log?.(`Backup written before applying ${pending.join(', ')}: ${file}`);
    }
  }
  const { db, pool } = createDb(url);
  try {
    await migrate(db, { migrationsFolder: migrationsFolder() });
  } finally {
    await pool.end();
  }
}

if (isEntryPoint(import.meta.url, 'migrate')) {
  Promise.resolve()
    .then(() => runMigrations(requireDatabaseUrl(), { backup: process.env.DB_BACKUP_BEFORE_MIGRATE !== 'false', log: console.log }))
    .then(() => console.log('Migrations applied'))
    .catch((e) => exitWithError(e));
}
